                s: `/api/assets/${id}/thumbnail/small?branchId=${api.branchId}`,
                m: `/api/assets/${id}/thumbnail/medium?branchId=${api.branchId}`,
                l: `/api/assets/${id}/thumbnail/large?branchId=${api.branchId}`,
